CREATE TABLE projects (
  id         TEXT PRIMARY KEY NOT NULL,
  root       TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE project_workspaces (
  id         TEXT PRIMARY KEY NOT NULL,
  project_id TEXT NOT NULL REFERENCES projects(id),
  path       TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  UNIQUE(path, project_id)
);

CREATE INDEX idx_project_workspaces_path ON project_workspaces(path);

CREATE TABLE authors (
  id          TEXT PRIMARY KEY,
  author_type TEXT NOT NULL DEFAULT 'human',
  name        TEXT NOT NULL,
  email       TEXT,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE UNIQUE INDEX idx_authors_name_email ON authors (name, email);

CREATE TABLE iterations (
  id           TEXT PRIMARY KEY,
  project_id   TEXT NOT NULL REFERENCES projects(id),
  title        TEXT NOT NULL,
  status       TEXT NOT NULL DEFAULT 'active',
  description  TEXT NOT NULL DEFAULT '',
  metadata     TEXT NOT NULL DEFAULT '{}',
  completed_at TEXT,
  created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_iterations_project_id ON iterations (project_id);
CREATE INDEX idx_iterations_status ON iterations (project_id, status);

CREATE TABLE tags (
  id         TEXT PRIMARY KEY,
  label      TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE entity_tags (
  entity_id   TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  tag_id      TEXT NOT NULL REFERENCES tags(id),
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (entity_type, entity_id, tag_id)
);
CREATE INDEX idx_entity_tags_tag_id ON entity_tags (tag_id);

CREATE TABLE notes (
  id          TEXT PRIMARY KEY,
  entity_id   TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  author_id   TEXT REFERENCES authors(id),
  body        TEXT NOT NULL,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_notes_entity ON notes (entity_type, entity_id);

CREATE TABLE relationships (
  id          TEXT PRIMARY KEY,
  rel_type    TEXT NOT NULL,
  source_id   TEXT NOT NULL,
  source_type TEXT NOT NULL,
  target_id   TEXT NOT NULL,
  target_type TEXT NOT NULL,
  created_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at  TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_relationships_source ON relationships (source_type, source_id);
CREATE INDEX idx_relationships_target ON relationships (target_type, target_id);
CREATE UNIQUE INDEX idx_relationships_unique
  ON relationships (rel_type, source_type, source_id, target_type, target_id);

CREATE TABLE iteration_tasks (
  iteration_id TEXT NOT NULL REFERENCES iterations(id),
  task_id      TEXT NOT NULL REFERENCES tasks(id),
  phase        INTEGER NOT NULL DEFAULT 1,
  created_at   TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (iteration_id, task_id)
);
CREATE INDEX idx_iteration_tasks_task_id ON iteration_tasks (task_id);

CREATE TABLE transactions (
  id         TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  author_id  TEXT REFERENCES authors(id),
  command    TEXT NOT NULL,
  undone_at  TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE INDEX idx_transactions_project_id ON transactions (project_id);
